function renderCalendarEnhanced(){const y=calendarCursor.getFullYear(),mo=calendarCursor.getMonth(),today=iso(new Date()),periods=allPeriods();document.querySelector('#calendarYearSelect').innerHTML=Array.from({length:new Date().getFullYear()-2014+2},(_,i)=>2014+i).map(v=>`<option value="${v}" ${v===y?'selected':''}>${v}年</option>`).join('');document.querySelector('#monthViewBtn').classList.toggle('active',calendarMode==='month');document.querySelector('#yearViewBtn').classList.toggle('active',calendarMode==='year');document.querySelector('.weekdays').hidden=calendarMode==='year';const grid=document.querySelector('#calendarGrid');if(calendarMode==='year'){document.querySelector('#calendarTitle').textContent=`${y}年`;grid.className='calendar-grid year-grid';grid.innerHTML=Array.from({length:12},(_,m)=>{const count=new Date(y,m+1,0).getDate(),offset=new Date(y,m,1).getDay();let cells='<span></span>'.repeat(offset);for(let d=1;d<=count;d++){const key=iso(new Date(y,m,d)),period=prioritizePeriods(periods.filter(x=>inRange(key,x.start,x.end)))[0],recorded=!!period,hasData=Boolean(state.logs[key]);cells+=`<button class="mini-day${recorded?' recorded':''}${period?.start===key?' period-start':''}${period?.end===key?' period-end':''}${hasData?' has-data':''}${key===today?' today':''}" data-date="${key}" aria-label="${key}${period?.start===key?' 月经开始':''}${period?.end===key?' 月经结束':''}">${d}</button>`}return `<section class="mini-month"><h3>${m+1}月</h3><div class="mini-days">${cells}</div></section>`}).join('');return}document.querySelector('#calendarTitle').textContent=`${y}年${mo+1}月`;grid.className='calendar-grid';const first=new Date(y,mo,1),start=new Date(y,mo,1-first.getDay()),p=phaseInfo();let html='';for(let i=0;i<42;i++){const d=new Date(start);d.setDate(start.getDate()+i);const key=iso(d),period=prioritizePeriods(periods.filter(x=>inRange(key,x.start,x.end)))[0],classes=['day',`phase-${phaseForDate(key)}`];if(d.getMonth()!==mo)classes.push('outside');if(key===today)classes.push('today');if(period){classes.push('recorded');if(period.start===key)classes.push('period-start');if(period.end===key)classes.push('period-end')}else if(inRange(key,p.windowStart,p.windowEnd))classes.push('predicted');html+=`<button class="${classes.join(' ')}" data-date="${key}" aria-label="${key}${period?.start===key?' 月经开始':''}${period?.end===key?' 月经结束':''}"><span class="day-number">${d.getDate()}</span></button>`}grid.innerHTML=html}

function explainCyclePoint(index){const item=cycleModel().intervals[index];if(!item)return;const end=addDays(item.start,item.length-1),status=item.length<21?'短于21天参考下限':item.length>35?'长于35天参考上限':'位于21–35天参考范围内';document.querySelector('#cyclePointDetail').innerHTML=`<strong>${item.start} → ${end}</strong><br>该周期为 <strong>${item.length}天</strong>，${status}。周期长度按本次月经首日至下次月经首日计算；单次变化只能用于记录趋势，不代表诊断。`}

document.querySelector('#monthViewBtn').addEventListener('click',()=>{calendarMode='month';renderView('calendar',{heavy:false})});document.querySelector('#yearViewBtn').addEventListener('click',()=>{calendarMode='year';renderView('calendar',{heavy:false})});document.querySelector('#calendarYearSelect').addEventListener('change',e=>{calendarCursor.setFullYear(Number(e.target.value));renderView('calendar',{heavy:false})});document.querySelector('#prevMonth').addEventListener('click',e=>{if(calendarMode!=='year')return;e.stopImmediatePropagation();calendarCursor.setFullYear(calendarCursor.getFullYear()-1);renderView('calendar',{heavy:false})},true);document.querySelector('#nextMonth').addEventListener('click',e=>{if(calendarMode!=='year')return;e.stopImmediatePropagation();calendarCursor.setFullYear(calendarCursor.getFullYear()+1);renderView('calendar',{heavy:false})},true);document.querySelector('#calendarGrid').addEventListener('click',e=>{const d=e.target.closest('.mini-day[data-date]');if(d)showDay(d.dataset.date)});document.querySelector('#cycleHistoryChart').addEventListener('click',e=>{const p=e.target.closest('circle[data-cycle-index]');if(p)explainCyclePoint(Number(p.dataset.cycleIndex))});document.querySelector('#cycleHistoryChart').addEventListener('keydown',e=>{const p=e.target.closest('circle[data-cycle-index]');if(p&&(e.key==='Enter'||e.key===' ')){e.preventDefault();explainCyclePoint(Number(p.dataset.cycleIndex))}});
document.querySelector('#calendarTodayBtn').addEventListener('click',()=>{calendarCursor=new Date();renderView('calendar',{heavy:false})});

if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js');
try{await loadBase();await pullRemote();const hash=location.hash.slice(1),initialView=['today','calendar','insights','more'].includes(hash)?hash:'today';showView(initialView,{render:false,behavior:'auto'});renderCurrentView({heavy:true});if(typeof requestIdleCallback==='function')requestIdleCallback(persistBaselineSnapshot,{timeout:1800});else setTimeout(persistBaselineSnapshot,500);checkStatus();if(localStorage.getItem(SYNC_PENDING_KEY)==='yes')scheduleSync(false)}catch(e){alertSystem('页面数据载入失败，请联网刷新或检查数据文件。','danger');safeLog('startup',e.name||'failed')}
